// Verkehrsabhängige Logik – wird jeden Takt (100 ms) ausgewertet.
const MIN_GREEN = 8;     // Sekunden
const MAX_GREEN = 40;
const GAP_LIMIT = 3.0;   // Zeitlücke für Grünende
var extensions = 0;

logic {
  if stage == Stage_1 {
    if stageTime < MIN_GREEN {
      hold;
    } else if stageTime >= MAX_GREEN {
      switch Stage_2;
    } else if gap(D1) < GAP_LIMIT {
      extend SG1 by 1;
      extensions = extensions + 1;
    } else {
      switch Stage_2;
    }
  } else if stage == Stage_2 and stageTime >= MIN_GREEN {
    if occupied(D1) or count(D1) >= 3 {
      switch Stage_1;
    }
  }
}

